"""Portable evidence viewer: no CDN, no server, no unsafe interpolated HTML."""
import json
from pathlib import Path


def render(rows, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = json.dumps(rows, ensure_ascii=False).replace("<", "\\u003c").replace("&", "\\u0026")
    path.write_text(TEMPLATE.replace("__DATA__", payload), encoding="utf-8")


TEMPLATE = r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>OrgLens — Norwegian company evidence</title>
<style>
:root{color-scheme:light;--ink:#142f35;--green:#087f69;--line:#d5e4e4}*{box-sizing:border-box}body{margin:0;background:#f2f7f6;color:var(--ink);font:16px/1.55 system-ui,sans-serif}header{background:#113d42;color:white;padding:26px max(20px,calc((100vw - 1280px)/2));}header p{color:#c3dfdb;margin:4px 0}h1{font-size:30px;margin:0}main{max-width:1320px;margin:24px auto;padding:0 20px}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:20px}input,select,button{font:inherit;padding:12px;border:1px solid var(--line);border-radius:9px;background:white;color:var(--ink)}input{flex:1;min-width:200px}button{cursor:pointer}button:hover{border-color:var(--green)}.layout{display:grid;grid-template-columns:310px 1fr;gap:20px}.list{max-height:78vh;overflow:auto}.item{display:block;width:100%;text-align:left;margin-bottom:8px}.item small{display:block;color:#547078}.item.active{border:2px solid var(--green)}.card{background:white;border:1px solid var(--line);border-radius:14px;padding:24px;margin-bottom:16px;overflow-wrap:anywhere}.eyebrow{color:var(--green);letter-spacing:.1em;font-size:12px;font-weight:700}h2{margin:8px 0;font-size:26px}h3{margin:0 0 12px}a{color:#086c78}pre{white-space:pre-wrap;background:#f3f7f7;padding:12px;border-radius:8px;font-size:13px}.state{display:inline-block;border-radius:20px;padding:3px 10px;background:#e4f3ee;margin:4px;font-size:13px}.unknown{background:#fff1d6}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.fact{border-top:1px solid var(--line);padding:12px 0}.muted{color:#587178}details{border-top:1px solid var(--line);padding:12px 0}summary{cursor:pointer}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:16px}@media(max-width:760px){.layout,.comparison{grid-template-columns:1fr}.list{max-height:220px}.card{padding:18px}header{padding:20px}h1{font-size:25px}} 
</style>
<header><h1>OrgLens <span style="font-weight:300">/ company research</span></h1><p>Every fact has a source. Every unknown stays visible.</p></header>
<main><div class="toolbar"><input id="search" aria-label="Search companies" placeholder="Search legal name or organisation number"><select id="filter" aria-label="Filter by website verification"><option value="all">All companies</option><option value="available">Verified website</option><option value="ambiguous">Identity needs review</option></select><button id="compare">Compare selected (0/2)</button><button id="download">Download JSON</button></div><p id="stats" class="muted"></p><div class="layout"><nav class="list" id="list" aria-label="Company results"></nav><section id="detail" aria-live="polite"></section></div></main>
<script id="data" type="application/json">__DATA__</script>
<script>
const rows=JSON.parse(document.getElementById('data').textContent), selected=new Set(); let current=rows[0], comparing=false;
const el=(tag,text,cls)=>{let n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
const name=r=>r.legal_identity.legal_name||r.organisation_number;
const pretty=v=>typeof v==='string'?v:JSON.stringify(v,null,2);
function sourceLink(url,label){let a=el('a',label);try{let p=new URL(url);if(['http:','https:'].includes(p.protocol)){a.href=p.href;a.target='_blank';a.rel='noopener noreferrer'}}catch{}return a}
function profile(r){let wrap=el('div');let card=el('div',undefined,'card');card.append(el('div',r.organisation_number,'eyebrow'),el('h2',name(r)),el('p','Researched '+r.run.completed_at,'muted'));let pick=el('button',selected.has(r.organisation_number)?'Remove from comparison':'Add to comparison');pick.onclick=()=>{let id=r.organisation_number;if(selected.has(id))selected.delete(id);else if(selected.size<2)selected.add(id);document.getElementById('compare').textContent='Compare selected ('+selected.size+'/2)';show()};card.append(pick);for(let s of r.summary.statements)card.append(el('p',s.text));card.append(el('p',r.changes.length+' recorded changes · '+r.claims.length+' supported claims','muted'));wrap.append(card);
let availability=el('div',undefined,'card');availability.append(el('h3','Research status'));for(let [k,v] of Object.entries(r.availability))availability.append(el('span',k.replaceAll('_',' ')+': '+v,'state '+(v==='available'?'':'unknown')));wrap.append(availability);
if(r.agent){let audit=el('details',undefined,'card');audit.append(el('summary','AI research audit · '+r.agent.status),el('p','Models choose tools; published facts require independent evidence verification.'),el('pre',pretty(r.agent)));wrap.append(audit)}else{let audit=el('div',undefined,'card');audit.append(el('p','Deterministic baseline — no model-directed tool loop in this result.','muted'));wrap.append(audit)}
let facts=el('div',undefined,'card');facts.append(el('h3','Facts and source evidence'));for(let c of r.claims){let d=el('details');d.append(el('summary',c.field.replaceAll('_',' ')),el('pre',pretty(c.value)));if(c.reporting_period)d.append(el('p','Reporting period: '+pretty(c.reporting_period)));for(let id of c.evidence_ids){let e=r.evidence.find(x=>x.id===id);if(!e)continue;d.append(sourceLink(e.source_url,'Open original source'),el('p','Retrieved '+e.retrieved_at+' · '+e.identity_method,'muted'),el('pre','SHA-256: '+e.content_sha256+'\nEvidence locator: '+pretty(e.locator)))}facts.append(d)}wrap.append(facts);
if(r.changes.length){let c=el('div',undefined,'card');c.append(el('h3','What changed'),el('pre',pretty(r.changes)));wrap.append(c)}if(r.refresh.last_known_claims.length){let c=el('div',undefined,'card');c.append(el('h3','Last known facts — refresh could not verify'),el('pre',pretty(r.refresh.last_known_claims)));wrap.append(c)}if(r.errors.length){let d=el('details',undefined,'card');d.append(el('summary','Research limitations ('+r.errors.length+')'),el('pre',pretty(r.errors)));wrap.append(d)}return wrap}
function show(){let detail=document.getElementById('detail');detail.replaceChildren();if(comparing&&selected.size===2){let grid=el('div',undefined,'comparison');for(let r of rows.filter(x=>selected.has(x.organisation_number)))grid.append(profile(r));detail.append(grid)}else if(current)detail.append(profile(current));}
function list(){let q=document.getElementById('search').value.toLowerCase(),f=document.getElementById('filter').value;let matches=rows.filter(r=>(name(r)+' '+r.organisation_number).toLowerCase().includes(q)&&(f==='all'||r.availability.official_website===f));let n=document.getElementById('list');n.replaceChildren();for(let r of matches){let b=el('button',name(r),'item'+(r===current?' active':''));b.append(el('small',r.organisation_number+' · '+r.claims.length+' facts'));b.onclick=()=>{current=r;comparing=false;list();show()};n.append(b)}document.getElementById('stats').textContent=matches.length+' of '+rows.length+' companies · Public-source research; missing information is not zero.';}
document.getElementById('search').oninput=list;document.getElementById('filter').onchange=list;document.getElementById('compare').onclick=()=>{comparing=!comparing;show()};document.getElementById('download').onclick=()=>{let url=URL.createObjectURL(new Blob([rows.map(r=>JSON.stringify(r)).join('\n')],{type:'application/x-ndjson'}));let a=el('a');a.href=url;a.download='orglens-envelopes.jsonl';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};list();show();
</script></html>'''
